const item = $input.first().json;
let datos = {};
try { datos = JSON.parse(item.datos_parciales || '{}'); } catch (e) { datos = {}; }
return [{
  json: {
    chat_id: item.chat_id,
    telegram_user: item.telegram_user,
    text: (item.text || '').trim(),
    paso_actual: item.paso_actual || '',
    row_number: Number(item.row_number),
    accion: datos.accion || '',
    id_tutor: datos.id_tutor || '',
    nombre_tutor: datos.nombre_tutor || '',
    dia: datos.dia || '',
    hora_inicio: datos.hora_inicio || '',
    franjas: datos.franjas || []
  }
}];

const tutor = $input.first().json;
const base = $('Parsear Datos Parciales').item.json;
return [{ json: {
  chat_id: base.chat_id,
  telegram_user: base.telegram_user,
  accion: base.accion,
  row_number: base.row_number,
  id_tutor: tutor.id_tutor || '',
  nombre_tutor: tutor.nombre || ''
} }];

const base = $('Preparar Accion').item.json;
const filas = $input.all().map(i => i.json);
let lista = 'No tienes franjas registradas todavia.';
if (filas.length > 0) {
  lista = filas.map(f => `${f.dia_semana} ${f.hora_inicio} a ${f.hora_fin} - ${f.estado}`).join('\n');
}
return [{ json: { chat_id: base.chat_id, telegram_user: base.telegram_user, row_number: base.row_number, mensaje: 'Tu agenda actual:\n' + lista } }];

const item = $input.first().json;
const dias = ['lunes','martes','miercoles','jueves','viernes','sabado','domingo'];
const capital = { lunes:'Lunes', martes:'Martes', miercoles:'Miercoles', jueves:'Jueves', viernes:'Viernes', sabado:'Sabado', domingo:'Domingo' };
const texto = (item.text || '').trim().toLowerCase();
const valido = dias.includes(texto);
return [{ json: { ...item, dia_valido: valido, dia_normalizado: valido ? capital[texto] : '' } }];

const item = $input.first().json;
const regex = /^([01]\d|2[0-3]):[0-5]\d$/;
const texto = (item.text || '').trim();
const valido = regex.test(texto);
return [{ json: { ...item, hora_inicio_valida: valido, hora_inicio_texto: texto } }];

const item = $input.first().json;
const regex = /^([01]\d|2[0-3]):[0-5]\d$/;
const texto = (item.text || '').trim();
const valido = regex.test(texto) && texto > item.hora_inicio;
return [{ json: { ...item, hora_fin_valida: valido, hora_fin_texto: texto } }];

const item = $input.first().json;
const id_dispo = 'DISP-' + Date.now().toString(36).toUpperCase();
return [{ json: { ...item, id_dispo } }];

const base = $('Preparar Accion').item.json;
const filas = $input.all().map(i => i.json).filter(f => (f.estado || '').trim().toLowerCase() === 'libre');
const franjas = filas.map(f => ({ id_dispo: f.id_dispo, dia_semana: f.dia_semana, hora_inicio: f.hora_inicio, hora_fin: f.hora_fin }));
const lista = franjas.map((f, idx) => `${idx+1}. ${f.dia_semana} ${f.hora_inicio} a ${f.hora_fin}`).join('\n');
return [{ json: {
  chat_id: base.chat_id,
  telegram_user: base.telegram_user,
  row_number: base.row_number,
  hay_franjas: franjas.length > 0,
  mensaje: franjas.length > 0 ? ('Elige la franja que quieres marcar como ocupada:\n' + lista) : 'No tienes franjas libres para marcar como ocupadas.',
  datos_parciales_json: JSON.stringify({ franjas })
} }];

const item = $input.first().json;
const idx = parseInt((item.text || '').trim(), 10) - 1;
const franjas = item.franjas || [];
const valido = !isNaN(idx) && idx >= 0 && idx < franjas.length;
const elegida = valido ? franjas[idx] : null;
return [{ json: { ...item, seleccion_valida: valido, franja_elegida: elegida } }];
